{"command": "node --input-type=module -e "
import { callTool, listTools } from './server.mjs';
import assert from 'node:assert/strict';

// tool discovery
const tools = await listTools();
console.log('tools:', tools.map(t=>t.name));

// isolation: b cannot see a's value
await callTool('open_client',{client_id:'a'});
await callTool('open_client',{client_id:'b'});
await callTool('client_put',{client_id:'a',key:'secret',value:'x'});
const got = await callTool('client_get',{client_id:'a',key:'secret'});
console.log('a gets:', got.content[0].text);
await assert.rejects(()=>callTool('client_get',{client_id:'b',key:'secret'}), /unknown key/);
console.log('isolation OK');

// unknown client
await assert.rejects(()=>callTool('client_get',{client_id:'ghost',key:'k'}), /unknown client/);
console.log('unknown client rejected');

// unknown tool
await assert.rejects(()=>callTool('bogus',{}), /unknown tool/);
console.log('unknown tool rejected');

// non-empty string validation
await assert.rejects(()=>callTool('open_client',{client_id:''}));
await assert.rejects(()=>callTool('client_put',{client_id:'a',key:'',value:'v'}));
await assert.rejects(()=>callTool('client_put',{client_id:'a',key:'k',value:123}));
console.log('validation OK');

// independent maps
await callTool('client_put',{client_id:'b',key:'k',value:'other'});
const bgot = await callTool('client_get',{client_id:'b',key:'k'});
console.log('b gets own:', bgot.content[0].text);
assert.equal(bgot.content[0].text,'other');
console.log('ALL OK');
""}

